def _mat(n, edges):
    inf = float('inf')
    matrix = [[inf] * n for _ in range(n)]
    for i in range(n):
        matrix[i][i] = 0
    for u, v, w in edges:
        matrix[u][v] = w
        matrix[v][u] = w
    return matrix

_n = 60
_edges = [(i, i + 1, (i * 11) % 9 + 1) for i in range(_n - 1)]
_edges += [((i * 17) % _n, (i * 13 + 7) % _n, (i * 5) % 12 + 1) for i in range(_n)]
_edges = [(u, v, w) for u, v, w in _edges if u != v]
_g = _mat(_n, _edges)
_pairs = {}
for _u in range(_n):
